function BuscarPeticiones(format=false){
	var ok = false;
	if ($('#univpet').val() != "") ok = true;
	if ($('#titulpet').val() != "") ok = true;
	if ($('#familia').val() != "") ok = true;
	if ($('#anio').val() != "") ok = true;

	if (ok){

		univpet = $('#univpet').val();
		titulpet = $('#titulpet').val();
		anio = $('#anio').val();
		familia = $('#familia').val();

		if (format == "xls"){
			$('#datos').attr("action", "g_not_cor_anteriores_xls.php");
			$('#datos').submit();
		}
		else if (format == "csv"){
			$('#datos').attr("action", "g_not_cor_anteriores_csv.php");
			$('#datos').submit();
		}
		else{
			$('body').css('cursor', 'progress');
			$('#btn_buscar').html("Buscando...");
			$('#svg-spinner').toggleClass("d-none");

			$.ajax({
			    url: 'g_not_cor_anteriores.php',
			    type: 'POST',
			    data: { univpet: univpet, titulpet: titulpet, anio: anio, familia: familia },
			    success : function(response) {
			    	$('#btn_buscar').html('Buscar');
			    	$('#svg-spinner').toggleClass("d-none");
			        $('#datos_busqueda').html(response);
			        $('body').css('cursor', 'initial');
			    }
			});
		}

	}else
		alert("Debe seleccionar al menos un criterio.");
}
